SELECT analytics_order_facts.category, SUM(analytics_order_facts.contribution_margin) AS contribution_margin FROM analytics_order_facts WHERE analytics_order_facts.year = 2023 AND analytics_order_facts.month = 3 AND analytics_order_facts.region = 'North' AND analytics_order_facts.channel = 'online' AND analytics_order_facts.customer_segment = 'education' AND analytics_order_facts.category = 'category_12' GROUP BY analytics_order_facts.category ORDER BY contribution_margin DESC, analytics_order_facts.category ASC LIMIT 10
